import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import toast from "react-hot-toast";
import {
  FiNavigation,
  FiPlusCircle,
  FiSearch,
  FiMapPin,
  FiX,
  FiCheckCircle
} from "react-icons/fi";

const SellerLocationPickerMap = ({ addressInfo, setAddressInfo }) => {
  const [locationMode, setLocationMode] = useState("manual"); // 'current' or 'manual'
  const [addressSearchQuery, setAddressSearchQuery] = useState("");
  const [suggestions, setSuggestions] = useState([]);
  const [isSearching, setIsSearching] = useState(false);
  const [showDropdown, setShowDropdown] = useState(false);
  const [geoLoading, setGeoLoading] = useState(false);
  const [coords, setCoords] = useState({ lat: null, lng: null });

  // Detailed address breakdown matching Cart Page design
  const [formData, setFormData] = useState({
    houseNo: "",
    landmark: "",
    area: "",
    city: "",
    state: "",
    pincode: "",
  });

  const dropdownRef = useRef(null);
  const searchTimeoutRef = useRef(null);
  const isInitialized = useRef(false);
  const baseURL = process.env.REACT_APP_BACKEND_URL || "";

  // Helper to extract and format Google Maps embed URL (supporting place URLs, iframe src, coords)
  const extractMapUrl = (raw) => {
    if (!raw) return "";
    let clean = raw.trim();

    // Check if it's an iframe embed tag
    const iframeSrcMatch = clean.match(/src=["']([^"']+)["']/i);
    if (iframeSrcMatch && iframeSrcMatch[1]) {
      clean = iframeSrcMatch[1].trim();
    }

    // If it's already an embed URL with params
    if (clean.includes("output=embed")) {
      return clean;
    }

    // Parse Google Maps /place/ or @lat,lng URLs
    // e.g., https://www.google.com/maps/place/Aditya+Pharmacy/@13.122297,77.628996,13z/...
    const atCoordMatch = clean.match(/@([0-9.-]+),([0-9.-]+)/);
    const dataCoordMatch = clean.match(/!3d([0-9.-]+)!4d([0-9.-]+)/);
    const placeMatch = clean.match(/\/place\/([^/@?]+)/);

    if (placeMatch && placeMatch[1]) {
      const placeName = decodeURIComponent(placeMatch[1].replace(/\+/g, " "));
      return `https://maps.google.com/maps?q=${encodeURIComponent(placeName)}&t=&z=13&ie=UTF8&iwloc=&output=embed`;
    }

    if (atCoordMatch && atCoordMatch[1] && atCoordMatch[2]) {
      const lat = atCoordMatch[1];
      const lng = atCoordMatch[2];
      return `https://maps.google.com/maps?q=${lat},${lng}&t=&z=13&ie=UTF8&iwloc=&output=embed`;
    }

    if (dataCoordMatch && dataCoordMatch[1] && dataCoordMatch[2]) {
      const lat = dataCoordMatch[1];
      const lng = dataCoordMatch[2];
      return `https://maps.google.com/maps?q=${lat},${lng}&t=&z=13&ie=UTF8&iwloc=&output=embed`;
    }

    // If it has q= query
    const qMatch = clean.match(/[?&]q=([^&]+)/);
    if (qMatch && qMatch[1]) {
      const qVal = decodeURIComponent(qMatch[1]);
      return `https://maps.google.com/maps?q=${encodeURIComponent(qVal)}&t=&z=13&ie=UTF8&iwloc=&output=embed`;
    }

    // Default if raw text/address provided
    return `https://maps.google.com/maps?q=${encodeURIComponent(clean)}&t=&z=13&ie=UTF8&iwloc=&output=embed`;
  };

  // Sync initial parent addressInfo into local formData ONCE when data is available
  useEffect(() => {
    if (addressInfo && !isInitialized.current) {
      if (addressInfo.line1 || addressInfo.houseNo || addressInfo.landmark || addressInfo.city || addressInfo.state || addressInfo.pincode) {
        setFormData((prev) => ({
          ...prev,
          houseNo: addressInfo.houseNo || prev.houseNo,
          landmark: addressInfo.landmark || addressInfo.line2 || prev.landmark,
          area: addressInfo.line1 || prev.area,
          city: addressInfo.city || prev.city,
          state: addressInfo.state || prev.state,
          pincode: addressInfo.pincode || prev.pincode,
        }));
        isInitialized.current = true;
      }

      if (addressInfo.mapLocation) {
        const cleanUrl = extractMapUrl(addressInfo.mapLocation);
        const atMatch = cleanUrl.match(/@([0-9.-]+),([0-9.-]+)/) || cleanUrl.match(/q=([0-9.-]+),([0-9.-]+)/) || cleanUrl.match(/!3d([0-9.-]+)!4d([0-9.-]+)/);
        if (atMatch && atMatch[1] && atMatch[2]) {
          setCoords({ lat: parseFloat(atMatch[1]), lng: parseFloat(atMatch[2]) });
        }
      }
    }
  }, [addressInfo]);

  // Click outside to close dropdown
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setShowDropdown(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Update parent addressInfo state for MongoDB basicInformation saving
  const updateParentAddress = (updatedForm, newCoords = coords) => {
    const addressLine1Value = (updatedForm.area || "").trim();

    let mapEmbed = addressInfo?.mapLocation || "";
    if (newCoords.lat && newCoords.lng) {
      const queryPart = addressLine1Value || `${newCoords.lat},${newCoords.lng}`;
      mapEmbed = `https://maps.google.com/maps?q=${encodeURIComponent(queryPart)}&t=&z=13&ie=UTF8&iwloc=&output=embed`;
    } else {
      const fullQuery = [
        updatedForm.houseNo,
        addressLine1Value,
        updatedForm.landmark,
        updatedForm.city,
        updatedForm.state,
        updatedForm.pincode,
      ]
        .filter(Boolean)
        .join(", ");
      if (fullQuery) {
        mapEmbed = `https://maps.google.com/maps?q=${encodeURIComponent(fullQuery)}&t=&z=13&ie=UTF8&iwloc=&output=embed`;
      }
    }

    setAddressInfo({
      houseNo: updatedForm.houseNo || "",
      landmark: updatedForm.landmark || "",
      line1: addressLine1Value,
      line2: updatedForm.landmark || "",
      city: updatedForm.city || "",
      state: updatedForm.state || "",
      pincode: updatedForm.pincode || "",
      mapLocation: mapEmbed,
    });
  };

  // Handle local form input change
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    const updated = { ...formData, [name]: value };
    setFormData(updated);
    updateParentAddress(updated);
  };

  // Handle Autocomplete Search
  const handleAddressSearchChange = (e) => {
    const val = e.target.value;
    setAddressSearchQuery(val);

    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    if (!val || val.trim().length < 2) {
      setSuggestions([]);
      setShowDropdown(false);
      setIsSearching(false);
      return;
    }

    setIsSearching(true);
    searchTimeoutRef.current = setTimeout(async () => {
      try {
        const res = await axios.get(`${baseURL}/api/location/autocomplete`, {
          params: { input: val },
        });

        if (res.data && res.data.predictions && Array.isArray(res.data.predictions)) {
          setSuggestions(res.data.predictions);
          setShowDropdown(true);
        } else {
          setSuggestions([]);
        }
      } catch (err) {
        console.error("Address autocomplete search error", err);
      } finally {
        setIsSearching(false);
      }
    }, 400);
  };

  // Helper to construct full address combining main text & secondary text
  const buildFullLocationAddress = (item, placeDetails = null) => {
    const mainText = (item?.structured_formatting?.main_text || placeDetails?.name || "").trim();
    const secondaryText = (item?.structured_formatting?.secondary_text || placeDetails?.formatted_address || "").trim();
    const itemDesc = (item?.description || "").trim();
    const formattedAddress = (placeDetails?.formatted_address || placeDetails?.details?.address || "").trim();

    // If item description is available and contains both main and secondary text
    if (itemDesc) {
      if (mainText && !itemDesc.toLowerCase().includes(mainText.toLowerCase())) {
        return `${mainText}, ${itemDesc}`;
      }
      return itemDesc;
    }

    // If place details returned formatted_address, ensure main_text is prefixed if missing
    if (formattedAddress) {
      if (mainText && !formattedAddress.toLowerCase().includes(mainText.toLowerCase())) {
        return `${mainText}, ${formattedAddress}`;
      }
      return formattedAddress;
    }

    // Combine main_text and secondary_text
    if (mainText && secondaryText) {
      if (!secondaryText.toLowerCase().includes(mainText.toLowerCase())) {
        return `${mainText}, ${secondaryText}`;
      }
      return secondaryText;
    }

    return mainText || secondaryText || "";
  };

  // Select place suggestion
  const handleSelectSuggestion = async (item) => {
    setShowDropdown(false);
    let fullAddr = buildFullLocationAddress(item);
    setAddressSearchQuery(fullAddr);

    toast.loading("Fetching location details...", { id: "place-toast" });

    try {
      let lat = item.lat;
      let lng = item.lng;
      let details = item.details || {};

      // If place_id is available, fetch full place details
      if (item.place_id && !item.place_id.startsWith("osm_")) {
        const res = await axios.get(`${baseURL}/api/location/place-details`, {
          params: { place_id: item.place_id },
        });
        if (res.data && res.data.success) {
          lat = res.data.lat || lat;
          lng = res.data.lng || lng;
          details = res.data.details || details;
          fullAddr = buildFullLocationAddress(item, res.data);
        }
      }

      setAddressSearchQuery(fullAddr);

      const newCoords = lat && lng ? { lat: Number(lat), lng: Number(lng) } : coords;
      if (lat && lng) setCoords(newCoords);

      const updatedForm = {
        ...formData,
        area: fullAddr,
        city: details.city || formData.city,
        state: details.state || formData.state,
        pincode: details.pincode || formData.pincode,
      };

      setFormData(updatedForm);
      updateParentAddress(updatedForm, newCoords);
      toast.success("Address selected & map updated!", { id: "place-toast" });
    } catch (err) {
      console.error("Place details error", err);
      const fallbackAddr = buildFullLocationAddress(item);
      setFormData((prev) => ({ ...prev, area: fallbackAddr }));
      toast.error("Set address text", { id: "place-toast" });
    }
  };

  // GPS Current Location Detection
  const handleUseCurrentLocation = () => {
    if (!navigator.geolocation) {
      toast.error("Geolocation is not supported by your browser");
      return;
    }

    setLocationMode("current");
    setGeoLoading(true);
    toast.loading("Detecting your current location...", { id: "geo-toast" });

    navigator.geolocation.getCurrentPosition(
      async (position) => {
        try {
          const { latitude, longitude } = position.coords;
          const newCoords = { lat: latitude, lng: longitude };
          setCoords(newCoords);

          const res = await axios.get(`${baseURL}/api/location/reverse-geocode`, {
            params: { lat: latitude, lng: longitude },
          });

          const data = res.data;
          if (data && (data.details || data.formatted_address)) {
            const details = data.details || {};
            const displayAddress = details.address || data.formatted_address || "";

            const updatedForm = {
              ...formData,
              area: displayAddress,
              city: details.city || formData.city,
              state: details.state || formData.state,
              pincode: details.pincode || formData.pincode,
            };

            setFormData(updatedForm);
            setAddressSearchQuery(displayAddress);
            updateParentAddress(updatedForm, newCoords);
            toast.success("Location retrieved successfully!", { id: "geo-toast" });
          } else {
            toast.error("Could not determine address details", { id: "geo-toast" });
          }
        } catch (err) {
          console.error("Reverse geocoding error", err);
          toast.error("Failed to fetch address details", { id: "geo-toast" });
        } finally {
          setGeoLoading(false);
        }
      },
      (error) => {
        setGeoLoading(false);
        switch (error.code) {
          case error.PERMISSION_DENIED:
            toast.error("Location permission denied by user.", { id: "geo-toast" });
            break;
          case error.POSITION_UNAVAILABLE:
            toast.error("Location information is unavailable.", { id: "geo-toast" });
            break;
          case error.TIMEOUT:
            toast.error("Location request timed out.", { id: "geo-toast" });
            break;
          default:
            toast.error("Error getting location.", { id: "geo-toast" });
            break;
        }
      },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  };

  // Active Map Embed URL
  const activeMapSrc = (() => {
    if (coords.lat && coords.lng) {
      const placeQuery = formData.area ? `${formData.area}` : `${coords.lat},${coords.lng}`;
      return `https://maps.google.com/maps?q=${encodeURIComponent(placeQuery)}&t=&z=13&ie=UTF8&iwloc=&output=embed`;
    }

    const clean = extractMapUrl(addressInfo?.mapLocation);
    if (clean) return clean;

    const queryStr = [formData.houseNo, formData.area, formData.city, formData.state, formData.pincode]
      .filter(Boolean)
      .join(", ");

    if (queryStr) {
      return `https://maps.google.com/maps?q=${encodeURIComponent(queryStr)}&t=&z=13&ie=UTF8&iwloc=&output=embed`;
    }

    return `https://maps.google.com/maps?q=12.9716,77.5946&t=&z=13&ie=UTF8&iwloc=&output=embed`;
  })();

  return (
    <div className="w-100">
      <div className="row g-4 align-items-stretch">
        {/* Left Side: Interactive Map Preview (Matching Cart Page Layout) */}
        <div className="col-lg-5 col-12 d-flex flex-column">
          <div className="d-flex align-items-center justify-content-between mb-2">
            <h5 className="font-16 fw-800 text-heading m-0">Location Map</h5>
          </div>
          <div
            className="flex-grow-1 rounded-4 overflow-hidden border shadow-xs"
            style={{
              backgroundColor: "#ffffff",
              minHeight: "440px",
              borderColor: "#E2E8F0",
            }}
          >
            <iframe
              title="Delivery Location Map"
              width="100%"
              height="100%"
              style={{ border: 0, width: "100%", height: "100%", minHeight: "440px", display: "block" }}
              loading="lazy"
              allowFullScreen
              src={activeMapSrc}
            ></iframe>
          </div>
        </div>

        {/* Right Side: Address Form (Matching Cart Page Layout) */}
        <div className="col-lg-7 col-12">
          <div className="d-flex align-items-center justify-content-between mb-3 border-bottom pb-2">
            <h5 className="font-16 fw-800 text-heading m-0">Address Details</h5>
          </div>

          {/* Select Location Option Pills */}
          <div className="mb-3">
            <label className="form-label" style={{ fontSize: "13px", fontWeight: "700", color: "#334155", marginBottom: "8px" }}>
              Select Location Option
            </label>
            <div className="row g-3">
              {/* Option 1: Use Current Location */}
              <div className="col-sm-6">
                <div
                  onClick={handleUseCurrentLocation}
                  style={{
                    border: locationMode === "current" ? "2px solid #A847F0" : "1.5px solid #E2E8F0",
                    backgroundColor: locationMode === "current" ? "#F5EEFC" : "#F8FAFC",
                    borderRadius: "12px",
                    padding: "10px 14px",
                    cursor: "pointer",
                    display: "flex",
                    alignItems: "center",
                    gap: "12px",
                    transition: "all 0.2s ease",
                    boxShadow: locationMode === "current" ? "0 4px 12px rgba(168, 71, 240, 0.12)" : "none",
                  }}
                >
                  <div
                    style={{
                      width: "36px",
                      height: "36px",
                      borderRadius: "50%",
                      backgroundColor: locationMode === "current" ? "#A847F0" : "#E2E8F0",
                      color: locationMode === "current" ? "#ffffff" : "#64748B",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      flexShrink: 0,
                    }}
                  >
                    {geoLoading ? (
                      <div className="spinner-border spinner-border-sm text-light" style={{ width: "16px", height: "16px" }} role="status"></div>
                    ) : (
                      <FiNavigation size={18} />
                    )}
                  </div>
                  <div>
                    <h5 style={{ fontSize: "13px", fontWeight: "700", color: "#1E293B", margin: "0 0 2px 0" }}>
                      Use Current Location
                    </h5>
                    <p style={{ fontSize: "11px", color: "#64748B", margin: 0 }}>
                      Auto-detect via GPS
                    </p>
                  </div>
                </div>
              </div>

              {/* Option 2: Add New Address */}
              <div className="col-sm-6">
                <div
                  onClick={() => setLocationMode("manual")}
                  style={{
                    border: locationMode === "manual" ? "2px solid #A847F0" : "1.5px solid #E2E8F0",
                    backgroundColor: locationMode === "manual" ? "#F5EEFC" : "#F8FAFC",
                    borderRadius: "12px",
                    padding: "10px 14px",
                    cursor: "pointer",
                    display: "flex",
                    alignItems: "center",
                    gap: "12px",
                    transition: "all 0.2s ease",
                    boxShadow: locationMode === "manual" ? "0 4px 12px rgba(168, 71, 240, 0.12)" : "none",
                  }}
                >
                  <div
                    style={{
                      width: "36px",
                      height: "36px",
                      borderRadius: "50%",
                      backgroundColor: locationMode === "manual" ? "#A847F0" : "#E2E8F0",
                      color: locationMode === "manual" ? "#ffffff" : "#64748B",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      flexShrink: 0,
                    }}
                  >
                    <FiPlusCircle size={18} />
                  </div>
                  <div>
                    <h5 style={{ fontSize: "13px", fontWeight: "700", color: "#1E293B", margin: "0 0 2px 0" }}>
                      Add New Address
                    </h5>
                    <p style={{ fontSize: "11px", color: "#64748B", margin: 0 }}>
                      Enter address manually
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Search Address / Location (Only displayed for "Add New Address") */}
          {locationMode === "manual" && (
            <div className="position-relative mb-3" ref={dropdownRef}>
              <label className="form-label" style={{ fontSize: "13px", fontWeight: "700", color: "#334155", marginBottom: "6px" }}>
                Search Address / Location
              </label>
              <div className="position-relative w-100">
                <input
                  type="text"
                  className="form-control common-input border"
                  placeholder="Search landmark, street, area, or city..."
                  value={addressSearchQuery}
                  onChange={handleAddressSearchChange}
                  onFocus={() => {
                    if (suggestions.length > 0) setShowDropdown(true);
                  }}
                  style={{
                    paddingRight: "40px",
                    borderRadius: "10px",
                    borderColor: "#CBD5E1",
                    fontSize: "14px",
                  }}
                />
                <div
                  style={{
                    position: "absolute",
                    right: "14px",
                    top: "50%",
                    transform: "translateY(-50%)",
                    color: "#94A3B8",
                    display: "flex",
                    alignItems: "center",
                    pointerEvents: "none",
                  }}
                >
                  {isSearching ? (
                    <div className="spinner-border spinner-border-sm" style={{ width: "16px", height: "16px", color: "#A847F0" }} role="status"></div>
                  ) : (
                    <FiSearch size={18} />
                  )}
                </div>
              </div>

              {/* Dropdown Suggestions matching Image 1 */}
              {showDropdown && suggestions.length > 0 && (
                <div
                  style={{
                    position: "absolute",
                    top: "100%",
                    left: 0,
                    right: 0,
                    zIndex: 1050,
                    backgroundColor: "#ffffff",
                    border: "1.5px solid #CBD5E1",
                    borderRadius: "12px",
                    marginTop: "4px",
                    boxShadow: "0 10px 25px rgba(0,0,0,0.1)",
                    maxHeight: "220px",
                    overflowY: "auto",
                  }}
                >
                  {suggestions.map((item, idx) => (
                    <div
                      key={item.place_id || idx}
                      onClick={() => handleSelectSuggestion(item)}
                      style={{
                        padding: "14px 20px",
                        cursor: "pointer",
                        borderBottom: idx === suggestions.length - 1 ? "none" : "1px solid #F1F5F9",
                        display: "flex",
                        alignItems: "flex-start",
                        gap: "14px",
                        transition: "background-color 0.15s ease",
                      }}
                      onMouseEnter={(e) => (e.currentTarget.style.backgroundColor = "#F5EEFC")}
                      onMouseLeave={(e) => (e.currentTarget.style.backgroundColor = "#ffffff")}
                    >
                      <FiMapPin style={{ color: "#A847F0", marginTop: "3px", flexShrink: 0 }} size={18} />
                      <div>
                        <div style={{ fontSize: "14px", fontWeight: "700", color: "#1E293B", lineHeight: "1.3" }}>
                          {item.structured_formatting?.main_text || item.description?.split(",")[0]}
                        </div>
                        <div style={{ fontSize: "12px", color: "#64748B", marginTop: "4px", lineHeight: "1.4" }}>
                          {item.structured_formatting?.secondary_text || item.description}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {/* House / Floor / Flat Number & Landmark */}
          <div className="row g-3 mb-3">
            <div className="col-sm-6">
              <label className="form-label fw-600 text-heading small mb-1">
                House / Floor / Flat Number <span className="text-danger">*</span>
              </label>
              <input
                type="text"
                name="houseNo"
                required
                className="common-input border"
                placeholder="e.g. Flat 402, 4th Floor"
                value={formData.houseNo}
                onChange={handleInputChange}
                style={{ borderRadius: "10px" }}
              />
            </div>
            <div className="col-sm-6">
              <label className="form-label fw-600 text-heading small mb-1">
                Landmark (Optional)
              </label>
              <input
                type="text"
                name="landmark"
                className="common-input border"
                placeholder="e.g. Near City Hospital"
                value={formData.landmark}
                onChange={handleInputChange}
                style={{ borderRadius: "10px" }}
              />
            </div>
          </div>

          {/* Area Details */}
          <div className="mb-3">
            <label className="form-label fw-600 text-heading small mb-1">
              Area Details <span className="text-danger">*</span>
            </label>
            <textarea
              name="area"
              required
              rows="3"
              className="common-input border p-3"
              placeholder="Street name, Locality, Area"
              value={formData.area}
              onChange={handleInputChange}
              style={{ height: "auto", resize: "vertical", borderRadius: "10px" }}
            ></textarea>
          </div>

          {/* City, State, Pincode */}
          <div className="row g-3">
            <div className="col-sm-4">
              <label className="form-label fw-600 text-heading small mb-1">
                City <span className="text-danger">*</span>
              </label>
              <input
                type="text"
                name="city"
                required
                className="common-input border"
                placeholder="City/District"
                value={formData.city}
                onChange={handleInputChange}
                style={{ borderRadius: "10px" }}
              />
            </div>
            <div className="col-sm-4">
              <label className="form-label fw-600 text-heading small mb-1">
                State <span className="text-danger">*</span>
              </label>
              <input
                type="text"
                name="state"
                required
                className="common-input border"
                placeholder="State"
                value={formData.state}
                onChange={handleInputChange}
                style={{ borderRadius: "10px" }}
              />
            </div>
            <div className="col-sm-4">
              <label className="form-label fw-600 text-heading small mb-1">
                Pincode <span className="text-danger">*</span>
              </label>
              <input
                type="text"
                name="pincode"
                required
                className="common-input border"
                placeholder="6-digit PIN"
                value={formData.pincode}
                onChange={handleInputChange}
                style={{ borderRadius: "10px" }}
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SellerLocationPickerMap;
